/**
 * 프로그래매틱 SEO 5축 — 업종별 "솔루션·시스템 구축"
 * 라우트: /solution/[industry]
 *
 * 검색 의도 분리(자기잠식 방지):
 *  - /app/[industry]    : 무엇을 만드나 (핵심 기능·운영 시나리오)
 *  - /cost/[industry]   : 얼마가 드나 (가격대·비용 요인·절감)
 *  - /solution/[industry]: 어떻게 구축하나 (기능 모듈 구성·기술 스택·연동·도입 로드맵)
 *
 * "솔루션/시스템 구축/디지털 전환" 검색 의도에 대응한다. 본문은 모듈·연동·단계 중심으로
 * 구성해 /app(기능·시나리오)과 겹치지 않게 하고, 솔루션 페이지끼리만 중복 검사한다.
 */
