export interface SolutionPhase {
  /** 단계 (1차 MVP / 2차 / 3차) */
  phase: string;
  /** 그 단계에서 구축하는 범위 (업종 고유) */
  detail: string;
}

export interface SolutionDef {
  /** IndustryDef.slug 와 동일 */
  slug: string;
  /** 솔루션 관점 도입부 (업종 고유, /app·/cost 와 겹치지 않게) */
  lead: string;
  /** 기능 모듈 구성 (업종 고유) */
  modules: string[];
  /** 기술 스택·구성 한 문단 */
  stack: string;
  /** 연동 포인트 (업종 고유) */
  integrations: string[];
  /** 단계별 도입 로드맵 (업종 고유) */
  roadmap: SolutionPhase[];
  /** 솔루션 특화 FAQ 3개 */
  faqs: { q: string; a: string }[];
  /** 왜 이렇게 구축하나 — 도입 관점 한 문단 (loop로 주입, 본문 깊이 보강) */
  why?: string;
}

