for (const s of SOLUTIONS) s.why = SOLUTION_WHY[s.slug];

// ─────────────────────────────────────────────────────────────
// 헬퍼
// ─────────────────────────────────────────────────────────────
const SOLUTION_BY_SLUG = Object.fromEntries(SOLUTIONS.map((s) => [s.slug, s]));

export function getSolution(slug: string): SolutionDef | undefined {
  return SOLUTION_BY_SLUG[slug];
}
export function allSolutionSlugs(): string[] {
  return SOLUTIONS.map((s) => s.slug);
}
export function hasSolution(slug: string): boolean {
  return Boolean(SOLUTION_BY_SLUG[slug]);
}
export function solutionCanonical(slug: string): string {
  return `${SITE.domain}/solution/${slug}/`;
}

/** 솔루션 페이지 표시명 — 업종명 + "솔루션·시스템 구축" */
export function solutionTitleName(slug: string): string {
  const ind = getIndustry(slug);
  const base = ind?.ko ?? slug;
  return `${base} 솔루션`;
}

/**
 * 솔루션 페이지의 검색결과 문구.
 * 이 축의 의도는 "어떻게 구축하나"다 — 모듈 구성·기술 스택·도입 순서.
 * 문형을 slug 시드로 갈라 113개가 같은 문장으로 늘어서지 않게 하고,
 * description 은 그 업종의 실제 모듈·스택에서 조립한다.
 */
export function solutionTitle(slug: string): string {
  const s = getSolution(slug);
  return buildSolutionTitle(solutionTitleName(slug), s?.modules, slug);
}

export function solutionDescription(slug: string): string {
  const s = getSolution(slug);
  const name = solutionTitleName(slug);
  if (!s) return `${name} 구축 기준을 정리했습니다. 단계별 도입 · 소스코드 이관.`;
  return buildSolutionDescription({
    name,
    modules: s.modules,
    integrations: s.integrations,
    lead: s.lead,
  });
}

/** 자기잠식 판정용 */
export function solutionIntentProfile(slug: string): IntentProfile | null {
  const ind = getIndustry(slug);
  return ind ? solutionProfile(`${ind.ko} 솔루션`) : null;
}

/**
 * 솔루션 페이지 색인 판정 — 렌더되는 본문(lead·modules·stack·integrations·roadmap·FAQ)에서
 * 신호를 측정한다. peerFingerprints 는 다른 솔루션 페이지의 고유 지문(lead+modules+integrations)과
 * 대조해 솔루션 페이지끼리의 중복만 검사한다(/app·/cost 와는 검색 의도가 분리됨).
 * 내부링크: 브레드크럼 2 + /app 대응 1 + /cost 대응 1 + 다른 솔루션 min(6) + 하단 요금 1.
 */
export function solutionDecision(slug: string): IndexDecision | null {
  const s = getSolution(slug);
  if (!s) return null;
  const ind = getIndustry(slug);
  const name = solutionTitleName(slug);
  const others = SOLUTIONS.filter((x) => x.slug !== s.slug);
  const internalLinks = 2 + 1 + 1 + Math.min(others.length, 6) + 1;
  return decideFromContent({
    title: solutionTitle(slug),
    description: solutionDescription(slug),
    h1: `${name} 구축`,
    bodyParts: [
      s.lead,
      s.modules,
      s.stack,
      s.integrations,
      s.roadmap.map((p) => `${p.phase} ${p.detail}`),
      s.why,
      ...s.faqs.map((f) => f.a),
      ind?.coreFeatures,
    ],
    faqQuestions: s.faqs.map((f) => f.q),
    internalLinks,
    hasUniqueMedia: false,
    peerFingerprints: others.map((x) => fingerprint(`${x.lead} ${x.modules.join(' ')} ${x.integrations.join(' ')}`)),
  });
}
